"""Cross-language conformance tests.

Compares Python RPC encoder output byte-for-byte against golden values
generated by the TypeScript implementation, ensuring both produce identical
wire format.
"""
import sys
from protocol.unity_protocol import (
    encode_rpc_subsequent, encode_rpc_first_use, decode_rpc,
    RPCMode, USER_RPC_CONSTANT, METHOD_TAG_MAP,
    register_method_tag,
)


# Golden values generated by ts/src/unity/rpc.ts
GOLDEN = {
    'sub_int_42': {
        'hex': '1b00000000000100000b5400000034200000000002a0',
        'bits': 172,
        'params': {'methodName': 'RPC_Int', 'params': [42], 'viewId': 1,
                   'rpcCounter': 0, 'mode': RPCMode.Server},
    },
    'sub_void': {
        'hex': '1b00000000000100000b5000000014200000',
        'bits': 140,
        'params': {'methodName': 'RPC_Void', 'params': [], 'viewId': 1,
                   'rpcCounter': 0, 'mode': RPCMode.Server},
    },
    'sub_int_42_c500': {
        'hex': '1b00000000000103e80b5400000034200000000002a0',
        'bits': 172,
        'params': {'methodName': 'RPC_Int', 'params': [42], 'viewId': 1,
                   'rpcCounter': 500, 'mode': RPCMode.Server},
    },
    'fu_int_42': {
        'hex': '1b00000000000100000b800000100c93b276d5b1d456000000034200000000002a',
        'bits': 264,
        'params': {'methodName': 'RPC_Int', 'params': [42], 'viewId': 1,
                   'rpcCounter': 0, 'mode': RPCMode.Server},
    },
    'fu_void': {
        'hex': '1b00000000000100000b800000120c93b276d5b155e84700000001420000',
        'bits': 240,
        'params': {'methodName': 'RPC_Void', 'params': [], 'viewId': 1,
                   'rpcCounter': 0, 'mode': RPCMode.Server},
    },
    'sub_int_42_player': {
        'hex': '1b00000000000100000b540000003520003000000150',
        'bits': 173,
        'params': {'methodName': 'RPC_Int', 'params': [42], 'viewId': 1,
                   'rpcCounter': 0, 'mode': RPCMode.Player},
    },
}

GOLDEN_TAG = {
    'fu_int_42_tag8': {
        'hex': '1b00000000000100000b800000100c93b276d5b1d456800000034200000000002a',
        'bits': 264,
        'params': {'methodName': 'RPC_Int', 'params': [42], 'viewId': 1,
                   'rpcCounter': 0, 'mode': RPCMode.Server},
        'tag': ('RPC_Int', 8),
    },
}


def _encode(entry, first_use=False):
    p = entry['params']
    fn = encode_rpc_first_use if first_use else encode_rpc_subsequent
    return fn(p['methodName'], p['params'], p['viewId'], p['rpcCounter'], p['mode'])


def test_subsequent_int42_matches_ts():
    data, bits = _encode(GOLDEN['sub_int_42'])
    assert data.hex() == GOLDEN['sub_int_42']['hex']
    assert bits == GOLDEN['sub_int_42']['bits']


def test_subsequent_void_matches_ts():
    data, bits = _encode(GOLDEN['sub_void'])
    assert data.hex() == GOLDEN['sub_void']['hex']
    assert bits == GOLDEN['sub_void']['bits']


def test_subsequent_counter500_matches_ts():
    data, bits = _encode(GOLDEN['sub_int_42_c500'])
    assert data.hex() == GOLDEN['sub_int_42_c500']['hex']
    assert bits == GOLDEN['sub_int_42_c500']['bits']


def test_first_use_int42_matches_ts():
    data, bits = _encode(GOLDEN['fu_int_42'], first_use=True)
    assert data.hex() == GOLDEN['fu_int_42']['hex']
    assert bits == GOLDEN['fu_int_42']['bits']


def test_first_use_void_matches_ts():
    data, bits = _encode(GOLDEN['fu_void'], first_use=True)
    assert data.hex() == GOLDEN['fu_void']['hex']
    assert bits == GOLDEN['fu_void']['bits']


def test_subsequent_player_mode_matches_ts():
    data, bits = _encode(GOLDEN['sub_int_42_player'])
    assert data.hex() == GOLDEN['sub_int_42_player']['hex']
    assert bits == GOLDEN['sub_int_42_player']['bits']


def test_first_use_with_method_tag_matches_ts():
    entry = GOLDEN_TAG['fu_int_42_tag8']
    name, tag = entry['tag']
    register_method_tag(name, tag)
    try:
        data, bits = _encode(entry, first_use=True)
        assert data.hex() == entry['hex']
        assert bits == entry['bits']
    finally:
        METHOD_TAG_MAP.pop(name, None)


def test_ts_golden_decodes_correctly():
    """All golden TS values decode to expected fields in Python."""
    for name, entry in GOLDEN.items():
        raw = bytes.fromhex(entry['hex'])
        decoded = decode_rpc(raw, entry['bits'])
        p = entry['params']
        assert decoded['rpc_counter'] == p['rpcCounter'], \
            f"{name}: counter {decoded['rpc_counter']} != {p['rpcCounter']}"
        assert decoded['method_name'] == p['methodName'], \
            f"{name}: method {decoded['method_name']} != {p['methodName']}"
        if p['params']:
            assert decoded['params'] == p['params'], \
                f"{name}: params {decoded['params']} != {p['params']}"


def test_user_rpc_constant_0x2000_in_wire():
    """The 0x2000 constant appears in the wire format at the expected position."""
    data, bits = _encode(GOLDEN['sub_int_42'])
    all_bits = ''.join(f'{b:08b}' for b in data)
    const_start = 120
    const_val = int(all_bits[const_start:const_start + 16], 2)
    assert const_val == 0x2000, f"Expected 0x2000, got 0x{const_val:04x}"


def test_16bit_counter_in_wire():
    """Counter=500 is encoded as 16-bit value 0x03E8 in the wire format."""
    data, _ = _encode(GOLDEN['sub_int_42_c500'])
    assert data[7] == 0x03  # high byte
    assert data[8] == 0xE8  # low byte


if __name__ == '__main__':
    import traceback
    tests = [v for k, v in sorted(globals().items()) if k.startswith('test_')]
    passed = failed = 0
    for t in tests:
        try:
            t()
            passed += 1
            print(f'  PASS  {t.__name__}')
        except Exception as e:
            failed += 1
            print(f'  FAIL  {t.__name__}: {e}')
            traceback.print_exc()
    print(f'\n{passed} passed, {failed} failed')
    sys.exit(1 if failed else 0)
